from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NEW_YORK)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.MINUTE).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.RAW)

        option = self.AddOption("SPY", Resolution.MINUTE)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 90))

        self.closes = RollingWindow[float](21)
        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.pending_entry_signal = False
        self.held_contract = None
        self.entry_fill_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_exit_ticket = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        # An actual consolidated bar is required; no missing intervals are filled.
        self.closes.Add(float(bar.Close))

        # Need 21 bars to calculate both current and preceding 20-bar SMAs.
        if self.closes.Count < 21:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        bar_end = bar.EndTime
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self.pending_entry_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProtection()

        if self.held_contract is not None:
            self.HandleOptionExit(slice)

        if not self.pending_entry_signal:
            return

        # A signal is evaluated once only, on the Slice that contains its close.
        self.pending_entry_signal = False

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.HasOpenEntryOrder():
            return

        self.TryEnter(slice)

    def TryEnter(self, slice):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain.")
            return

        spot = float(self.Securities[self.spy].Price)
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Entry skipped: no qualifying call expiration.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in calls)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no 1% OTM call at nearest expiry.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def HandleOptionExit(self, slice):
        holding = self.Portfolio[self.held_contract]
        if holding.Quantity <= 0:
            return

        expiration_date = self.held_contract.ID.Date.date()
        previous_trading_day = self.PreviousSpyTradingDay(expiration_date)

        if self.Time.date() == previous_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitOptionExit("time stop")
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or self.entry_fill_price is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitOptionExit("profit target")

    def HandleExpirationProtection(self):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if holding.Quantity <= 0:
            return

        expiration_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiration_date:
            self.no_entry_date = self.Time.date()
            self.SubmitOptionExit("expiration protection")

    def SubmitOptionExit(self, reason):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if holding.Quantity == 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            return

        # Cancel any pending order for this contract before submitting its exit.
        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.held_contract, -holding.Quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def HandleUnexpectedSpyHolding(self):
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Quantity == 0:
            return

        if self.equity_exit_ticket is None or not self.equity_exit_ticket.Status.IsOpen():
            self.equity_exit_ticket = self.MarketOrder(self.spy, -spy_holding.Quantity)
            self.Debug("Unexpected SPY exercise/assignment holding: liquidation submitted.")

    def PreviousSpyTradingDay(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while not exchange.DateIsOpen(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def HasOpenEntryOrder(self):
        return self.entry_ticket is not None and self.entry_ticket.Status.IsOpen()

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.FILLED and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_contract} @ {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(f"Exit filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}")
                if self.held_contract == order_event.Symbol:
                    self.held_contract = None
                    self.entry_fill_price = None
                self.exit_ticket = None

        if self.equity_exit_ticket is not None and order_event.OrderId == self.equity_exit_ticket.OrderId:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug("Unexpected SPY holding liquidated.")
                self.equity_exit_ticket = None

