        self.time_stop_submitted_date = None
        self.no_entries_on_date = None
        self.spy_flatten_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        self.five_minute_closes.Add(float(bar.Close))

        if not self.five_minute_closes.IsReady:
            return

        closes = [self.five_minute_closes[i] for i in range(self.five_minute_closes.Count)]
        fast = sum(closes[:5]) / 5.0
        slow = sum(closes[:20]) / 20.0

        crossed_up = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not crossed_up:
            return

        bar_end = bar.EndTime
        eligible_time = (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and
            (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        )

        if eligible_time:
            self.pending_entry_bar_end = bar_end

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_contract is not None:
            self.HandleExpirationExit()
            self.HandleTimeStop()
            self.HandleProfitTarget(slice)

        if self.pending_entry_bar_end == self.Time:
            self.pending_entry_bar_end = None
            self.TryEnter(slice)

