            return

        if self.held_contract is not None or self.Portfolio[self.held_contract].Invested:
            return

        if self.entry_ticket is not None:
            return

        if self.exit_ticket is not None:
            return

        if self.spy_flatten_ticket is not None:
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        spot = float(self.Securities[self.spy].Price)

        if spot <= 0:
            self.Debug(f"{self.Time}: Entry skipped: SPY price unavailable.")
            return

        earliest_date = self.Time.date() + timedelta(days=7)

        eligible_expirations = sorted({
            contract.Expiry
            for contract in chain
            if contract.Expiry.date() >= earliest_date
        })

        if not eligible_expirations:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no qualifying call for {selected_expiry.date()}."
            )
            return

