        self.held_contract = selected.Symbol
        self.contract_expiry = selected.Expiry
        self.entry_fill_price = None
        self.entry_ticket = self.MarketOrder(self.held_contract, 1)

        self.Debug(
            f"{self.Time}: Entering 1 {self.held_contract} "
            f"(strike {selected.Strike}, expiry {selected.Expiry.date()})."
        )

    def HandleProfitTarget(self, slice):
