        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("profit target")

    def HandleTimeStop(self):
        if self.exit_ticket is not None or self.contract_expiry is None:
            return

        prior_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.contract_expiry
        )

        if (
            self.Time.date() == prior_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
            and self.time_stop_submitted_date != self.Time.date()
        ):
            self.time_stop_submitted_date = self.Time.date()
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationExit(self):
        if self.contract_expiry is None:
            return

        if self.Time.date() >= self.contract_expiry.date():
            self.no_entries_on_date = self.Time.date()

            if self.exit_ticket is None and self.Portfolio[self.held_contract].Invested:
                self.SubmitExit("expiration-day protection")

    def SubmitExit(self, reason):
        if self.exit_ticket is not None or self.held_contract is None:
            return

        if self.entry_ticket is not None:
            self.entry_ticket.Cancel("Exit requested before entry completion.")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"{self.Time}: Exiting {self.held_contract}: {reason}.")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if self.spy_flatten_ticket is not None:
            return

        quantity = self.Portfolio[self.spy].Quantity
        self.no_entries_on_date = self.Time.date()
        self.Debug(
            f"{self.Time}: Unexpected SPY position from exercise/assignment; flattening {quantity} shares."
        )
        self.spy_flatten_ticket = self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == 0:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
                self.entry_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order did not fill: {order_event.Status}.")
                self.entry_ticket = None
                if self.held_contract is not None and not self.Portfolio[self.held_contract].Invested:
                    self.held_contract = None
                    self.contract_expiry = None
                    self.entry_fill_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {order_event.Symbol}.")
                self.exit_ticket = None
                self.held_contract = None
                self.contract_expiry = None
                self.entry_fill_price = None
                self.time_stop_submitted_date = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

        if (
            self.spy_flatten_ticket is not None
            and order_event.OrderId == self.spy_flatten_ticket.OrderId
            and order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]
        ):
            self.spy_flatten_ticket = None
